net.coobird.thumbnailator.geometry.Position position = net.coobird.thumbnailator.geometry.Positions.BOTTOM_RIGHT;
java.awt.Point placement = position.calculate(
    800, 600, // enclosingWidth, enclosingHeight
    200, 100, // width, height
    10, 20, 30, 40 // insetLeft, insetRight, insetTop, insetBottom
);

// For BOTTOM_RIGHT, X = enclosingWidth - width - insetRight = 800 - 200 - 20 = 580
// For BOTTOM_RIGHT, Y = enclosingHeight - height - insetBottom = 600 - 100 - 40 = 460
assert placement.x == 580 : "Expected X coordinate to be 580, but got " + placement.x;
assert placement.y == 460 : "Expected Y coordinate to be 460, but got " + placement.y;

System.out.println("__CHECK__ calculate " + placement.x + "," + placement.y);

